// DropAdminServiceClient is the client API for DropAdminService service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// DropAdminService edits the drop divisor table (issue 34).
//
// DropRate[64] is code in tmServer (tmserver/internal/loot, Basedef.cpp:222) and
// the value is a DIVISOR per Carry slot: 1 = always drops, 20000 = ultra rare.
// The rarity of an item is decided by the slot it occupies in the mob's Carry[],
// not by the item itself. Each edit is an overlay row in drop_rate_override;
// tmServer applies the rows ONCE at boot, behind `-drop-config-editing`, so an
// edit needs a restart. With the flag off the table is exactly the code defaults.
type DropAdminServiceClient interface {
	// ListDropRates returns all 64 slots with the code value, the effective value
	// and whether an overlay row exists.
	ListDropRates(ctx context.Context, in *ListDropRatesRequest, opts ...grpc.CallOption) (*ListDropRatesResponse, error)
	// UpsertDropRate stores one slot divisor (1..1000000).
	UpsertDropRate(ctx context.Context, in *UpsertDropRateRequest, opts ...grpc.CallOption) (*AdminAck, error)
	// ResetDropRate removes the overlay row, restoring the code value.
	ResetDropRate(ctx context.Context, in *ResetDropRateRequest, opts ...grpc.CallOption) (*AdminAck, error)
	// ListMobCarry returns one template's Carry[] as the world would load it:
	// 64 positions, the item of each, and whether an overlay row set it.
	ListMobCarry(ctx context.Context, in *ListMobCarryRequest, opts ...grpc.CallOption) (*ListMobCarryResponse, error)
	// SetMobCarry replaces the template's whole Carry[] table. Effects are not
	// taken from the request: a slot whose item did not change keeps its effects,
	// a new item starts with none (the web can't inject adds).
	SetMobCarry(ctx context.Context, in *SetMobCarryRequest, opts ...grpc.CallOption) (*AdminAck, error)
	// ResetMobCarry drops the template's overlay, returning it to the file.
	ResetMobCarry(ctx context.Context, in *ResetMobCarryRequest, opts ...grpc.CallOption) (*AdminAck, error)
}

